# Unit tests for the pure v1 -> v2 conversation-record import
# (`shinychat._history_import.import_v1_record`), plus the per-released-form
# fixture matrix harness further below.
#
# The matrix cases live in tests/shared/history-v1-import-matrix.json (one case
# per released v1 record form, bytes generated by each release's own writer) and
# are synced into pkg-r by `make r-sync-fixtures` for the Phase 6 R port.

from __future__ import annotations

from datetime import datetime, timezone
from typing import Any, cast

from shinychat._history_import import (
    import_v1_record,
    import_v1_record_with_warnings,
)
from shinychat._history_types import (
    ConversationNode,
    ConversationRecord,
    ConversationRecordV2,
)

NOW = datetime(2026, 10, 15, 12, 0, 0, tzinfo=timezone.utc)


def _ui(
    role: str, content: str, *, version: bool = True, **extra: Any
) -> dict[str, Any]:
    message: dict[str, Any] = {
        "role": role,
        "segments": [{"content": content, "content_type": "markdown"}],
    }
    if version:
        message["version"] = 1
    message.update(extra)
    return message


def _chatlas_turn(role: str, text: str) -> dict[str, Any]:
    return {
        "role": role,
        "contents": [{"content_type": "text", "text": text}],
    }


def _plain_turn(role: str, text: str) -> dict[str, Any]:
    return {"role": role, "content": text}


def _node(
    *,
    parent: str | None,
    children: list[str],
    turns: list[dict[str, Any]],
    ui: list[dict[str, Any]] | None,
    selected_child: str | None,
) -> ConversationNode:
    return ConversationNode(
        parent=parent,
        children=children,
        turns=turns,
        ui=ui,
        selected_child=selected_child,
    )


def _record(
    nodes: dict[str, ConversationNode],
    *,
    current_leaf: str | None,
    id: str = "c_import",
    values: dict[str, Any] | None = None,
) -> ConversationRecord:
    return ConversationRecord(
        id=id,
        title="Imported",
        created_at=NOW,
        updated_at=NOW,
        nodes=nodes,
        next_node_seq=len(nodes) + 1,
        current_leaf=current_leaf,
        values=values or {},
    )


def _linear_record(
    *, ui: list[dict[str, Any]] | None, turns: list[dict[str, Any]]
) -> ConversationRecord:
    """n1(user) -> n2(assistant), one exchange, versioned or derived UI."""
    return _record(
        {
            "n_0001": _node(
                parent=None,
                children=["n_0002"],
                turns=[turns[0]],
                ui=[ui[0]] if ui else None,
                selected_child="n_0002",
            ),
            "n_0002": _node(
                parent="n_0001",
                children=[],
                turns=[turns[1]],
                ui=[ui[1]] if ui else None,
                selected_child=None,
            ),
        },
        current_leaf="n_0002",
    )


def _display(record: ConversationRecordV2) -> list[tuple[str, str]]:
    """The exchange-tree display projection, straight off the record.

    Mirrors `_replay_exchange_display` without a chat or provider client:
    for each exchange on the active path, its input followed by its
    messages.
    """
    projected: list[tuple[str, str]] = []
    for nid in record.path_node_ids():
        node = record.nodes[nid]
        if node.input is not None:
            projected.append((node.input.role, node.input.content))
        for message in node.messages:
            stored = message.as_stored_message()
            projected.append((stored.role, stored.content))
    return projected


def _turns_deltas(record: ConversationRecordV2) -> list[dict[str, Any]]:
    """Fold the active path's turn-state entries, as restore does."""
    deltas: list[dict[str, Any]] = []
    for nid in record.path_node_ids():
        entry = record.nodes[nid].state.get("shinychat:turns")
        if entry is not None:
            deltas.extend(cast("list[dict[str, Any]]", entry.data))
    return deltas


def test_linear_record_pairs_into_one_exchange_per_turn() -> None:
    record = _linear_record(
        ui=[
            _ui("user", "Hello"),
            _ui("assistant", "Hi there"),
        ],
        turns=[
            _chatlas_turn("user", "Hello"),
            _chatlas_turn("assistant", "Hi there"),
        ],
    )
    imported, warns = import_v1_record_with_warnings(record)

    assert warns == []
    assert imported.schema_version == 2
    assert imported.active_leaf == "n_0002"
    assert set(imported.nodes) == {"n_0000", "n_0002"}
    root = imported.nodes["n_0000"]
    pair = imported.nodes["n_0002"]
    assert root.parent_id is None
    assert root.children == ["n_0002"]
    assert root.selected_child == "n_0002"
    assert root.status == "ok"
    assert pair.parent_id == "n_0000"
    assert pair.children == []
    assert pair.selected_child is None
    assert pair.status == "ok"
    assert pair.input is not None
    assert pair.input.role == "user"
    assert pair.input.content == "Hello"
    assert [m.as_stored_message().content for m in pair.messages] == [
        "Hi there"
    ]

    # Every synthesized node gets the record's created_at; v2's tie-break
    # falls to children-list order, matching v1's children[-1] fallback.
    assert all(
        node.created_at == imported.created_at
        for node in imported.nodes.values()
    )
    # v1 never stored the system prompt: per-exchange deltas, no root
    # snapshot. Folding from entry 0 reproduces v1's path_turns().
    assert "shinychat:turns" not in root.state
    assert _turns_deltas(imported) == record.path_turns()
    entry = pair.state["shinychat:turns"]
    assert entry.kind == "chatlas"
    assert entry.version == 1
    assert entry.mode == "delta"
    # Display needs no provider client: the projection walks the record.
    assert _display(imported) == [
        ("user", "Hello"),
        ("assistant", "Hi there"),
    ]


def test_derived_ui_uses_plain_turns_kind_without_warning() -> None:
    record = _linear_record(
        ui=None,
        turns=[
            _plain_turn("user", "Hello"),
            _plain_turn("assistant", "Hi there"),
        ],
    )
    imported, warns = import_v1_record_with_warnings(record)

    assert warns == []
    entry = imported.nodes["n_0002"].state["shinychat:turns"]
    assert entry.kind == "turns"
    assert _display(imported) == [
        ("user", "Hello"),
        ("assistant", "Hi there"),
    ]


def test_regenerate_responses_become_sibling_exchanges_sharing_input() -> None:
    record = _record(
        {
            "n_0001": _node(
                parent=None,
                children=["n_0002", "n_0003"],
                turns=[_chatlas_turn("user", "Hello")],
                ui=[_ui("user", "Hello")],
                selected_child="n_0003",
            ),
            "n_0002": _node(
                parent="n_0001",
                children=[],
                turns=[_chatlas_turn("assistant", "First try")],
                ui=[_ui("assistant", "First try")],
                selected_child=None,
            ),
            "n_0003": _node(
                parent="n_0001",
                children=[],
                turns=[_chatlas_turn("assistant", "Regenerated")],
                ui=[_ui("assistant", "Regenerated")],
                selected_child=None,
            ),
        },
        current_leaf="n_0003",
    )
    imported, warns = import_v1_record_with_warnings(record)

    assert warns == []
    assert imported.active_leaf == "n_0003"
    assert imported.nodes["n_0000"].children == ["n_0002", "n_0003"]
    assert imported.nodes["n_0000"].selected_child == "n_0003"
    first, regenerated = imported.nodes["n_0002"], imported.nodes["n_0003"]
    assert first.parent_id == regenerated.parent_id == "n_0000"
    assert first.input is not None and regenerated.input is not None
    assert first.input.content == regenerated.input.content == "Hello"
    assert [m.as_stored_message().content for m in first.messages] == [
        "First try"
    ]
    assert [m.as_stored_message().content for m in regenerated.messages] == [
        "Regenerated"
    ]
    # Each sibling owns only its own turn delta; both fold to v1's path.
    assert (
        imported.nodes["n_0002"].state["shinychat:turns"].data
        == record.nodes["n_0001"].turns + record.nodes["n_0002"].turns
    )


def test_multiple_roots_reparent_under_synthesized_root() -> None:
    record = _record(
        {
            "n_0001": _node(
                parent=None,
                children=["n_0002"],
                turns=[_chatlas_turn("user", "First")],
                ui=[_ui("user", "First")],
                selected_child="n_0002",
            ),
            "n_0002": _node(
                parent="n_0001",
                children=[],
                turns=[_chatlas_turn("assistant", "Answer one")],
                ui=[_ui("assistant", "Answer one")],
                selected_child=None,
            ),
            "n_0003": _node(
                parent=None,
                children=["n_0004"],
                turns=[_chatlas_turn("user", "Second")],
                ui=[_ui("user", "Second")],
                selected_child="n_0004",
            ),
            "n_0004": _node(
                parent="n_0003",
                children=[],
                turns=[_chatlas_turn("assistant", "Answer two")],
                ui=[_ui("assistant", "Answer two")],
                selected_child=None,
            ),
        },
        current_leaf="n_0004",
    )
    imported, warns = import_v1_record_with_warnings(record)

    assert warns == []
    root = imported.nodes["n_0000"]
    assert root.children == ["n_0002", "n_0004"]
    assert root.selected_child == "n_0004"
    assert imported.nodes["n_0002"].parent_id == "n_0000"
    assert imported.nodes["n_0004"].parent_id == "n_0000"
    assert imported.active_leaf == "n_0004"
    assert imported.path_node_ids() == ["n_0000", "n_0004"]


def test_foreign_ids_are_reused_verbatim() -> None:
    record = _record(
        {
            "custom-user": _node(
                parent=None,
                children=["custom-answer"],
                turns=[_plain_turn("user", "Hi")],
                ui=[_ui("user", "Hi")],
                selected_child="custom-answer",
            ),
            "custom-answer": _node(
                parent="custom-user",
                children=[],
                turns=[_plain_turn("assistant", "Hello")],
                ui=[_ui("assistant", "Hello")],
                selected_child=None,
            ),
        },
        current_leaf="custom-answer",
        id="c_foreign",
    )
    imported, warns = import_v1_record_with_warnings(record)

    assert warns == []
    assert set(imported.nodes) == {"n_0000", "custom-answer"}
    assert imported.nodes["n_0000"].children == ["custom-answer"]
    assert imported.active_leaf == "custom-answer"


def test_root_id_colliding_with_a_v1_node_id_mints_a_suffix() -> None:
    record = _record(
        {
            "n_0000": _node(
                parent=None,
                children=["n_0001"],
                turns=[_chatlas_turn("user", "Hello")],
                ui=[_ui("user", "Hello")],
                selected_child="n_0001",
            ),
            "n_0001": _node(
                parent="n_0000",
                children=[],
                turns=[_chatlas_turn("assistant", "Hi there")],
                ui=[_ui("assistant", "Hi there")],
                selected_child=None,
            ),
        },
        current_leaf="n_0001",
    )
    imported, warns = import_v1_record_with_warnings(record)

    assert warns == []
    # The v1 node n_0000 is a user node, not a root: the synthesized root
    # mints the next free id by membership check, never by parsing.
    assert "n_0000_1" in imported.nodes
    assert imported.nodes["n_0000_1"].parent_id is None
    assert imported.nodes["n_0001"].parent_id == "n_0000_1"
    assert imported.active_leaf == "n_0001"


def test_interrupted_input_becomes_cancelled_bare_exchange() -> None:
    # A user node whose continuation is another user node (v1's navigate-
    # and-edit shape): the first input keeps a bare exchange, the second
    # user node re-parents under it, and the response-less exchange is
    # retryable ("cancelled").
    record = _record(
        {
            "n_0001": _node(
                parent=None,
                children=["n_0002"],
                turns=[_chatlas_turn("user", "u1")],
                ui=[_ui("user", "u1")],
                selected_child="n_0002",
            ),
            "n_0002": _node(
                parent="n_0001",
                children=["n_0003"],
                turns=[_chatlas_turn("assistant", "a1")],
                ui=[_ui("assistant", "a1")],
                selected_child="n_0003",
            ),
            "n_0003": _node(
                parent="n_0002",
                children=["n_0004", "n_0005"],
                turns=[_chatlas_turn("user", "u2")],
                ui=[_ui("user", "u2")],
                selected_child="n_0005",
            ),
            "n_0004": _node(
                parent="n_0003",
                children=[],
                turns=[_chatlas_turn("assistant", "a2")],
                ui=[_ui("assistant", "a2")],
                selected_child=None,
            ),
            "n_0005": _node(
                parent="n_0003",
                children=["n_0006"],
                turns=[_chatlas_turn("user", "u2 edited")],
                ui=[_ui("user", "u2 edited")],
                selected_child="n_0006",
            ),
            "n_0006": _node(
                parent="n_0005",
                children=[],
                turns=[_chatlas_turn("assistant", "a2 edited")],
                ui=[_ui("assistant", "a2 edited")],
                selected_child=None,
            ),
        },
        current_leaf="n_0006",
    )
    imported, warns = import_v1_record_with_warnings(record)

    assert warns == []
    # n_0003 keeps a bare exchange (id n_0003) whose children are the
    # edited continuation; its original response pairs with it as a
    # sibling exchange under n_0002.
    bare = imported.nodes["n_0003"]
    assert bare.input is not None and bare.input.content == "u2"
    assert bare.messages == []
    assert bare.status == "cancelled"
    assert bare.children == ["n_0006"]
    assert bare.parent_id == "n_0002"
    assert imported.nodes["n_0004"].parent_id == "n_0002"
    assert imported.nodes["n_0002"].children == ["n_0004", "n_0003"]
    assert imported.nodes["n_0002"].selected_child == "n_0003"
    edited = imported.nodes["n_0006"]
    assert edited.parent_id == "n_0003"
    assert edited.input is not None and edited.input.content == "u2 edited"
    assert edited.status == "ok"
    assert imported.active_leaf == "n_0006"
    # Turn-prefix fidelity: the folded path equals v1's path turns, and
    # the display equals v1's stored UI along the path.
    assert _turns_deltas(imported) == record.path_turns()
    assert _display(imported) == [
        ("user", "u1"),
        ("assistant", "a1"),
        ("user", "u2"),
        ("user", "u2 edited"),
        ("assistant", "a2 edited"),
    ]


def test_unversioned_ui_with_extra_messages_warns_and_drops() -> None:
    record = _record(
        {
            "n_0001": _node(
                parent=None,
                children=[],
                turns=[_chatlas_turn("user", "Hello")],
                # Unversioned client-snapshot UI with an out-of-band extra
                # message: 0.7.2 discards it and re-derives one message.
                ui=[
                    _ui("user", "Hello", version=False),
                    _ui("assistant", "out of band", version=False),
                ],
                selected_child=None,
            ),
        },
        current_leaf="n_0001",
    )
    imported, warns = import_v1_record_with_warnings(record)

    assert warns == [
        "conversation c_import: node 'n_0001' carried 2 stored UI "
        "message(s) without a version marker, but only one display message "
        "can be re-derived from its turns; 1 message(s) were dropped"
    ]
    bare = imported.nodes["n_0001"]
    assert bare.status == "cancelled"
    assert bare.input is not None and bare.input.content == "Hello"
    assert bare.messages == []


def test_unversioned_ui_with_no_turns_warns_and_drops() -> None:
    record = _record(
        {
            "n_0001": _node(
                parent=None,
                children=[],
                turns=[],
                ui=[_ui("assistant", "orphaned snapshot", version=False)],
                selected_child=None,
            ),
        },
        current_leaf="n_0001",
    )
    imported, warns = import_v1_record_with_warnings(record)

    assert warns == [
        "conversation c_import: node 'n_0001' carried 1 stored UI "
        "message(s) but no turns to re-derive display from; the message(s) "
        "were dropped"
    ]
    node = imported.nodes["n_0001"]
    # Re-derivation from empty turns yields the empty assistant fallback
    # message, exactly what 0.7.2's replay displayed.
    assert node.input is None
    assert [m.as_stored_message().content for m in node.messages] == [""]


def test_versioned_system_ui_message_warns_and_drops() -> None:
    record = _record(
        {
            "n_0001": _node(
                parent=None,
                children=[],
                turns=[],
                ui=[_ui("system", "ambient prompt")],
                selected_child=None,
            ),
        },
        current_leaf="n_0001",
    )
    imported, warns = import_v1_record_with_warnings(record)

    assert warns == [
        "conversation c_import: node 'n_0001' had a stored UI message "
        "that cannot be represented in the exchange-tree record (system "
        "role); it was dropped"
    ]
    node = imported.nodes["n_0001"]
    assert node.input is None
    assert node.messages == []
    assert node.status == "ok"


def test_invalid_versioned_ui_message_warns_and_drops() -> None:
    record = _record(
        {
            "n_0001": _node(
                parent=None,
                children=[],
                turns=[],
                ui=[{"version": 1, "role": "user", "segments": "not a list"}],
                selected_child=None,
            ),
        },
        current_leaf="n_0001",
    )
    imported, warns = import_v1_record_with_warnings(record)

    assert len(warns) == 1
    assert warns[0].startswith(
        "conversation c_import: node 'n_0001' had a stored UI message "
        "that cannot be represented in the exchange-tree record (invalid "
        "message: "
    )
    assert "segments" in warns[0]
    assert warns[0].endswith("); it was dropped")
    node = imported.nodes["n_0001"]
    assert node.input is None
    assert node.messages == []


def test_dangling_current_leaf_warns_and_imports_best_effort_leaf() -> None:
    record = _record(
        {
            "n_0001": _node(
                parent=None,
                children=["n_0002"],
                turns=[_chatlas_turn("user", "Hello")],
                ui=[_ui("user", "Hello")],
                selected_child="n_0002",
            ),
            "n_0002": _node(
                parent="n_0001",
                children=[],
                turns=[_chatlas_turn("assistant", "Hi there")],
                ui=[_ui("assistant", "Hi there")],
                selected_child=None,
            ),
        },
        current_leaf="n_9999",
    )
    imported, warns = import_v1_record_with_warnings(record)

    assert warns == [
        "conversation c_import: current leaf 'n_9999' is not a node in "
        "this record; the best-effort leaf 'n_0002' was imported instead"
    ]
    # Best effort: follow the copied selected-child pointers from the root.
    assert imported.active_leaf == "n_0002"
    assert imported.path_node_ids() == ["n_0000", "n_0002"]


def test_missing_system_prompt_never_warns() -> None:
    # v1 never stored the system prompt; the import must neither synthesize
    # one nor warn about its absence.
    record = _linear_record(
        ui=[_ui("user", "Hello"), _ui("assistant", "Hi there")],
        turns=[
            _chatlas_turn("user", "Hello"),
            _chatlas_turn("assistant", "Hi there"),
        ],
    )
    imported, warns = import_v1_record_with_warnings(record)

    assert warns == []
    assert "shinychat:turns" not in imported.nodes["n_0000"].state
    assert _turns_deltas(imported) == record.path_turns()
    assert not any(
        "system" in turn.get("role", "") for turn in _turns_deltas(imported)
    )


def test_metadata_is_carried_verbatim() -> None:
    record = _linear_record(
        ui=[_ui("user", "Hello"), _ui("assistant", "Hi there")],
        turns=[
            _chatlas_turn("user", "Hello"),
            _chatlas_turn("assistant", "Hi there"),
        ],
    )
    record = record.model_copy(
        update={
            "title": "Renamed",
            "title_source": "user",
            "response_count": 3,
            "client_info": {"provider": "openai", "model": "gpt-4o"},
            "values": {"slider": "42"},
            "bookmark_state_id": "abc123",
            "next_node_seq": 7,
        }
    )
    imported = import_v1_record(record)

    assert imported.title == "Renamed"
    assert imported.title_source == "user"
    assert imported.response_count == 3
    assert imported.client_info == {"provider": "openai", "model": "gpt-4o"}
    assert imported.values == {"slider": "42"}
    assert imported.bookmark_state_id == "abc123"
    assert imported.next_node_seq == 7
    assert imported.id == record.id
    assert imported.created_at == record.created_at
    assert imported.updated_at == record.updated_at
